from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parent.parent
changes=[]
def patch(file,old,new):
    p=root/file;b=p.read_bytes();s=b.decode();nl='\r\n' if b'\r\n' in b else '\n'
    old=old.replace('\r\n','\n').replace('\n',nl);new=new.replace('\r\n','\n').replace('\n',nl)
    if s.count(old)!=1:raise ValueError(file+' nonunique anchor '+old[:100])
    p.write_bytes(s.replace(old,new).encode());changes.append({'file':file,'old':old,'new':new})

